          label: record.label,
        }),
        competitionId: record.competitionId,
        label: record.label,
      }));

      return {
        data,
        pagination: {
          nextCursor: createNextCursor(page.hasMore, page.records, (record) => ({
            competitionId: record.competitionId,
            label: record.label,
          })),
