    async getSeason(seasonId) {
      const identity = parseSeasonId(seasonId);

      if (!identity || !isDatabaseId(identity.competitionId)) {
        return null;
      }

      const record = await findSeason(identity.competitionId, identity.label);

      if (!record) {
