        ...(query.gender !== undefined ? { gender: query.gender } : {}),
        ...(query.startDateFrom !== undefined ? { startDateFrom: query.startDateFrom } : {}),
        ...(query.startDateTo !== undefined ? { startDateTo: query.startDateTo } : {}),
