export type AdminManagementConflictCode =
  | 'SELF_MANAGEMENT_NOT_ALLOWED'
  | 'ADMIN_ACCOUNT_NOT_MANAGEABLE'
  | 'DISABLED_ACCOUNT_NOT_MANAGEABLE';

export class AdminManagementConflictError extends Error {
  constructor(
    public readonly code: AdminManagementConflictCode,
    message: string,
  ) {
    super(message);
    this.name = 'AdminManagementConflictError';
  }
}

export class AdminUserNotFoundError extends Error {
  constructor() {
    super('The requested user does not exist.');
    this.name = 'AdminUserNotFoundError';
  }
}

export class InvalidCompetitionScopesError extends Error {
  constructor(public readonly competitionIds: string[]) {
    super(
      competitionIds.length === 1
        ? `Competition scope ${competitionIds[0]} does not exist.`
        : `Competition scopes ${competitionIds.join(', ')} do not exist.`,
    );
    this.name = 'InvalidCompetitionScopesError';
  }
}

import { Router } from 'express';

import type { VerifyAccessToken } from '../../auth/supabase-auth';
import { requireAuthentication } from '../../middleware/require-authentication';
import { requireAdministrator } from '../../middleware/require-authorization';
import type { SynchronizeAccount } from '../accounts/account.service';
import {
  createAdminListUsersController,
  createAdminUpdateSubmitterAccessController,
} from './admin.controller';
import type { AdminService } from './admin.service';

export function createAdminRouter(
  verifyAccessToken: VerifyAccessToken,
  synchronizeAccount: SynchronizeAccount,
  service: AdminService,
): Router {
  const router = Router();
  const authenticate = requireAuthentication(verifyAccessToken, synchronizeAccount);
  const authorize = requireAdministrator();

  router.get('/admin/users', authenticate, authorize, createAdminListUsersController(service));
  router.patch(
    '/admin/users/:userId/submitter-access',
    authenticate,
    authorize,
    createAdminUpdateSubmitterAccessController(service),
  );

  return router;
}

import type {
  AdministratorSubmitterAccessResponse,
  AdministratorSubmitterAccessUpdate,
  AdministratorUserManagementResponse,
} from '@sport-analytics/contracts';

import type { ApplicationAccount } from '../accounts/account';
import { AdminManagementConflictError } from './admin.errors';
import { createAdminRepository, type AdminRepository } from './admin.repository';

export interface AdminService {
  listUsers(): Promise<AdministratorUserManagementResponse>;
  updateSubmitterAccess(
    administrator: ApplicationAccount,
    targetAccountId: string,
    update: AdministratorSubmitterAccessUpdate,
  ): Promise<AdministratorSubmitterAccessResponse>;
}

export function createAdminService(repository?: AdminRepository): AdminService {
  let resolvedRepository = repository;

  function getRepository(): AdminRepository {
    resolvedRepository ??= createAdminRepository();
    return resolvedRepository;
  }

  return {
    async listUsers() {
      return { data: await getRepository().listUserManagementData() };
    },

    async updateSubmitterAccess(administrator, targetAccountId, update) {
      if (administrator.accountId === targetAccountId) {
        throw new AdminManagementConflictError(
          'SELF_MANAGEMENT_NOT_ALLOWED',
          'Administrators cannot change their own submitter access.',
        );
      }

      const user = await getRepository().updateSubmitterAccess(
        targetAccountId,
        administrator.accountId,
        update,
      );

      return { data: user };
    },
  };
}

