import { apiDateTimeSchema, apiIdentifierSchema } from './api';

export const APPLICATION_ROLES = ['viewer', 'submitter', 'admin'] as const;

export const applicationRoleSchema = z.enum(APPLICATION_ROLES);

/** @deprecated Request-workflow state only. Use applicationRoleSchema for authorization. */
export const submitterApprovalStateSchema = z.enum([
  'not_requested',
  'pending',
  'approved',
  'rejected',
]);

export const currentUserProfileSchema = z
  .object({
    id: apiIdentifierSchema,
    subject: z.string().min(1),
    displayName: z.string().min(1).nullable(),
    role: applicationRoleSchema,
    approvalState: submitterApprovalStateSchema,
    competitionIds: z
      .array(apiIdentifierSchema)
      .refine((competitionIds) => new Set(competitionIds).size === competitionIds.length, {
        message: 'Competition identifiers must be unique.',
      }),
  })
  .strict();

export const currentUserProfileResponseSchema = z
  .object({
    user: currentUserProfileSchema,
  })
  .strict();

export const submitterAccessRequestResponseSchema = z
  .object({
    data: z
      .object({
        accountId: apiIdentifierSchema,
        approvalState: z.literal('pending'),
      })
      .strict(),
  })
  .strict();

export const administratorCompetitionScopeSchema = z
  .object({
    competitionId: apiIdentifierSchema,
    name: z.string().min(1),
  })
  .strict();

export const administratorAuditActorSchema = z
  .object({
    id: apiIdentifierSchema,
    displayName: z.string().min(1).nullable(),
  })
  .strict();

export const administratorManagedUserSchema = z
  .object({
    id: apiIdentifierSchema,
    displayName: z.string().min(1).nullable(),
    role: applicationRoleSchema,
    approvalState: submitterApprovalStateSchema,
    competitionScopes: z
      .array(administratorCompetitionScopeSchema)
      .refine(
        (scopes) => new Set(scopes.map((scope) => scope.competitionId)).size === scopes.length,
        { message: 'Competition scopes must be unique.' },
      ),
    disabled: z.boolean(),
    updatedAt: apiDateTimeSchema,
    submitterAccessUpdatedAt: apiDateTimeSchema.nullable(),
    submitterAccessUpdatedBy: administratorAuditActorSchema.nullable(),
  })
  .strict();

export const administratorUserManagementResponseSchema = z
  .object({
    data: z
      .object({
        users: z.array(administratorManagedUserSchema),
        availableScopes: z
          .array(administratorCompetitionScopeSchema)
          .refine(
            (scopes) => new Set(scopes.map((scope) => scope.competitionId)).size === scopes.length,
            { message: 'Available competition scopes must be unique.' },
          ),
      })
      .strict(),
  })
  .strict();

export const administratorSubmitterAccessUpdateSchema = z
  .object({
    approved: z.boolean(),
    competitionIds: z
      .array(apiIdentifierSchema)
      .refine((competitionIds) => new Set(competitionIds).size === competitionIds.length, {
        message: 'Competition identifiers must be unique.',
      }),
  })
  .strict()
  .superRefine((value, context) => {
    if (value.approved && value.competitionIds.length === 0) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['competitionIds'],
        message: 'Select at least one competition scope before approving a submitter.',
      });
    }

    if (!value.approved && value.competitionIds.length > 0) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['competitionIds'],
        message: 'Revoked submitters cannot retain competition scopes.',
      });
    }
  });

export const administratorSubmitterAccessResponseSchema = z
  .object({
    data: administratorManagedUserSchema,
  })
  .strict();
export * from './errors';
export * from './pool';
export * from './query';
export * from './transaction';
import type { VerifiedIdentity } from '../../auth/supabase-auth';
import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';
import { isApplicationRole, isSubmitterApprovalState, type ApplicationAccount } from './account';

interface ApplicationAccountRow {
  accountId: string;
  subject: string;
  displayName: string | null;
  role: string;
  approvalState: string;
  competitionIds: string[];
  disabledAt: Date | null;
}

export async function synchronizeApplicationAccount(
  identity: VerifiedIdentity,
  executor: QueryExecutor = getDatabasePool(),
): Promise<ApplicationAccount> {
  const result = await executeQuery<ApplicationAccountRow>(
    executor,
    `
      WITH synchronized_account AS (
        INSERT INTO app_user (
          auth_provider,
          auth_subject,
          display_name,
          application_role,
          last_authenticated_at
        )
        VALUES ($1, $2, $3, 'viewer', now())
        ON CONFLICT (auth_provider, auth_subject) DO UPDATE
        SET
          display_name = COALESCE(EXCLUDED.display_name, app_user.display_name),
          last_authenticated_at = now()
        RETURNING
          app_user_id,
          auth_subject,
          display_name,
          application_role,
          submitter_approval_state,
          disabled_at
      )
      SELECT
        account.app_user_id::text AS "accountId",
        account.auth_subject AS subject,
        account.display_name AS "displayName",
        account.application_role AS role,
        account.submitter_approval_state AS "approvalState",
        COALESCE(
          array_agg(scope.competition_id::text ORDER BY scope.competition_id)
            FILTER (WHERE scope.competition_id IS NOT NULL),
          ARRAY[]::text[]
        ) AS "competitionIds",
        account.disabled_at AS "disabledAt"
      FROM synchronized_account account
      LEFT JOIN submitter_competition_scope scope
        ON scope.app_user_id = account.app_user_id
      GROUP BY
        account.app_user_id,
        account.auth_subject,
        account.display_name,
        account.application_role,
        account.submitter_approval_state,
        account.disabled_at
    `,
    ['supabase', identity.uid, identity.displayName ?? null],
  );

  const account = result.rows[0];

  if (!account) {
    throw new Error('Application account synchronization returned no account');
  }

  if (!isApplicationRole(account.role)) {
    throw new Error('Application account has an unsupported role');
  }

  if (!isSubmitterApprovalState(account.approvalState)) {
    throw new Error('Application account has an unsupported approval state');
  }

  return {
    accountId: account.accountId,
    subject: account.subject,
    displayName: account.displayName,
    role: account.role,
    approvalState: account.approvalState,
    competitionIds: account.competitionIds,
    disabled: account.disabledAt !== null,
  };
}
import cors from 'cors';
import express from 'express';
import helmet from 'helmet';
import pinoHttp from 'pino-http';
import { createSupabaseTokenVerifier, type VerifyAccessToken } from './auth/supabase-auth';
import { loadEnvironment, type Environment } from './config/env';
import { errorHandler } from './middleware/error-handler';
import { notFoundHandler } from './middleware/not-found';
import {
  createAccountSynchronizer,
  type SynchronizeAccount,
} from './modules/accounts/account.service';
import { createAuthRouter } from './routes/auth.routes';
import { healthRouter } from './routes/health.routes';
import { createPublicReadRouter } from './modules/public-read/public-read.routes';
import {
  createPublicReadService,
  type PublicReadService,
} from './modules/public-read/public-read.service';
import { createFixtureStatisticsRouter } from './modules/statistics/fixture-statistics.routes';
import {
  createFixtureStatisticsService,
  type FixtureStatisticsService,
} from './modules/statistics/fixture-statistics.service';
import { createSubmissionRouter } from './modules/submissions/submission.routes';
import {
  createSubmissionService,
  type SubmissionService,
} from './modules/submissions/submission.service';
import { createSubmitterAccessRouter } from './modules/submitter-access/submitter-access.routes';
import {
  createSubmitterAccessService,
  type SubmitterAccessService,
} from './modules/submitter-access/submitter-access.service';
import { createAdminRouter } from './modules/admin/admin.routes';
import { createAdminService, type AdminService } from './modules/admin/admin.service';

export interface AppDependencies {
  environment?: Environment;
  verifyAccessToken?: VerifyAccessToken;
  synchronizeAccount?: SynchronizeAccount;
  publicReadService?: PublicReadService;
  fixtureStatisticsService?: FixtureStatisticsService;
  submissionService?: SubmissionService;
  submitterAccessService?: SubmitterAccessService;
  adminService?: AdminService;
}

export function createApp(dependencies: AppDependencies = {}) {
  const environment = dependencies.environment ?? loadEnvironment();
  const verifyAccessToken =
    dependencies.verifyAccessToken ?? createSupabaseTokenVerifier(environment);
  const synchronizeAccount = dependencies.synchronizeAccount ?? createAccountSynchronizer();
  const publicReadService = dependencies.publicReadService ?? createPublicReadService();
  const fixtureStatisticsService =
    dependencies.fixtureStatisticsService ?? createFixtureStatisticsService();
  const submissionService = dependencies.submissionService ?? createSubmissionService();
  const submitterAccessService =
    dependencies.submitterAccessService ?? createSubmitterAccessService();
  const adminService = dependencies.adminService ?? createAdminService();
  const allowedOrigins = environment.CORS_ORIGINS.split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);

  const app = express();

  app.disable('x-powered-by');
  app.use(helmet());
  app.use(
    cors({
      origin: allowedOrigins,
      credentials: true,
    }),
  );
  app.use(express.json({ limit: '1mb' }));
  app.use(
    pinoHttp({
      redact: ['req.headers.authorization'],
    }),
  );

  app.use('/api/v1/health', healthRouter);
  app.use('/api/v1/auth', createAuthRouter(verifyAccessToken, synchronizeAccount));
  app.use('/api/v1', createFixtureStatisticsRouter(fixtureStatisticsService));
  app.use(
    '/api/v1',
    createSubmissionRouter(verifyAccessToken, synchronizeAccount, submissionService),
  );
  app.use(
    '/api/v1',
    createSubmitterAccessRouter(verifyAccessToken, synchronizeAccount, submitterAccessService),
  );
  app.use('/api/v1', createAdminRouter(verifyAccessToken, synchronizeAccount, adminService));
  app.use('/api/v1', createPublicReadRouter(publicReadService));

  app.use(notFoundHandler);
  app.use(errorHandler);

  return app;
}

